    [3235]={name="Ring of Scorn",sourceType="quest_reward",instructions="Reward from the quest “A Husband's Revenge”. In Silverpine Forest.",zone="Silverpine Forest",questName="A Husband's Revenge",lore="Valdred, once my good friend, was my wife's murderer. Although I am incapable of grieving, I do yearn for revenge. If you kill Valdred and bring me his cursed hands, then I will reward you."},
