    [19991]={name="Devilsaur Eye",sourceType="quest_reward",instructions="Reward from the quest “The Green Drake” — pick it over the other choices.",questName="The Green Drake",lore="Now I set you on a dangerous hunt to slay the green drake, Morphaz, and bring his tooth to me. Morphaz dwells deep in Temple of Atal'Hakkar, the entrance to which lies in Swamp of Sorrows.",proc="Use: Increases your attack power by 150 and your hit rating by 20.  Effect lasts for 20 sec. (2 Min Cooldown)"},
