    [21278]={name="Stormshroud Gloves",sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [21365]={name="Striker's Footguards",sourceType="quest_reward",instructions="Reward from the quest “Striker's Footguards”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Striker's Footguards",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21366]={name="Striker's Diadem",sourceType="quest_reward",instructions="Reward from the quest “Striker's Diadem”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Striker's Diadem",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21370]={name="Striker's Hauberk",sourceType="quest_reward",instructions="Reward from the quest “Striker's Hauberk”. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="Striker's Hauberk",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21463]={name="Ossirian's Binding",sourceType="boss_drop",instructions="Drops from Ossirian the Unscarred in Ruins of Ahn'Qiraj.",zone="Ruins of Ahn'Qiraj",npc="Ossirian the Unscarred",lore="A qiraji lieutenant holding the Ruins, whose name stopped being accurate the first time a raid used the crystals against him."},
    [21567]={name="Rune of Duty",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21568]={name="Rune of Duty",sourceType="vendor",instructions="Bought from Illiyana Moonblaze in Mor'shan Base Camp — costs tokens or reputation.",zone="Mor'shan Base Camp",npc="Illiyana Moonblaze"},
    [21599]={name="Vek'lor's Gloves of Devastation",sourceType="boss_drop",instructions="Drops from Emperor Vek'lor in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Emperor Vek'lor",lore="Twin emperor of the qiraji, and the one who inherited C'Thun's gift for magic instead of his brother's strength. Neither twin can be killed far from the other."},
    [21664]={name="Barbed Choker",sourceType="boss_drop",instructions="Drops from Fankriss the Unyielding in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="Fankriss the Unyielding",lore="A vast qiraji burrower that spawns its young mid-fight and hurls intruders into the walls."},
    [21701]={name="Cloak of Concentrated Hatred",sourceType="boss_drop",instructions="Drops from The Prophet Skeram in Temple of Ahn'Qiraj.",zone="Temple of Ahn'Qiraj",npc="The Prophet Skeram",lore="C'Thun's mouthpiece. Everything the qiraji believe, they believe because he told them the Old God said it."},
    [21710]={name="Cloak of the Fallen God",sourceType="quest_reward",instructions="Reward from the quest “The Savior of Kalimdor” — pick it over the other choices. In Ahn'Qiraj.",zone="Ahn'Qiraj",questName="The Savior of Kalimdor",lore="To the Caverns of Time you go, Lord:Lady;. Anachronos awaits your return. Give him the eye of C'Thun as he will undoubtedly wish to place it in his master's collection."},
    [22013]={name="Beastmaster's Cap",sourceType="quest_reward",instructions="Reward from the quest “Saving the Best for Last”. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22060]={name="Beastmaster's Tunic",sourceType="quest_reward",instructions="Reward from the quest “Saving the Best for Last”. In Ironforge.",zone="Ironforge",questName="Saving the Best for Last",lore="That's an amazing story! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut."},
    [22150]={name="Beads of Ogre Might",sourceType="quest_reward",instructions="Reward from the quest “Falrin's Vendetta” — pick it over the other choices. In Dire Maul.",zone="Dire Maul",questName="Falrin's Vendetta",lore="Yet I'm not one to give out favors freely, even if you were sent here by an old friend. I hold nothing but hatred and contempt for our brutish ogre neighbors."},
    [22207]={name="Sash of the Grand Hunt",sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan in Blackrock Depths.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay."},
