    [22436]={name="Cryptstalker Tunic",sourceType="quest_reward",instructions="Reward from the quest “Cryptstalker Tunic”. In Naxxramas.",zone="Naxxramas",questName="Cryptstalker Tunic",lore="I have discovered a use for the carapace of the crypt fiend. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas."},
