    [23071]={name="Leggings of Apocalypse",sourceType="object_drop",instructions="Found in Bottle of Disease.",npc="Bottle of Disease"},
    [23206]={name="Mark of the Champion",sourceType="quest_reward",instructions="Reward from the quest “The Fall of Kel'Thuzad” — pick it over the other choices. In Naxxramas.",zone="Naxxramas",questName="The Fall of Kel'Thuzad",lore="Struck for the war against the Scourge and the Old Gods. It does nothing at all against anything else, which is the point of the mark."},
    [23242]={name="Claw of the Frost Wyrm",sourceType="boss_drop",instructions="Drops from Sapphiron.",npc="Sapphiron",lore="A blue dragon slain in Northrend and raised as a frost wyrm. He guards the final approach to Kel'Thuzad's chamber."},
    [23323]={name="Crown of the Fire Festival",sourceType="quest_reward",instructions="Reward from the quest “A Thief's Reward”.",questName="A Thief's Reward",seasonal=true,lore="This flame, stolen from the heart of Stormwind itself, floods you with warmth. This raw power is foreign to you, but the (NAME) might know more..."},
    [23324]={name="Mantle of the Fire Festival",sourceType="quest_reward",instructions="Reward from the quest “Wild Fires in the Eastern Kingdoms”.",questName="Wild Fires in the Eastern Kingdoms",seasonal=true,lore="Our celebration of the flame is spread throughout the land. Not a single place remains untouched by the heat of this holiday, and the strongest fires burn a brilliant blue."},
